bash: cd /app && python -c "
import mujoco
m = mujoco.MjModel.from_xml_path('model_ref.xml')
# List all attributes
attrs = [a for a in dir(m) if not a.startswith('_')]
for a in attrs:
    try:
        v = getattr(m, a)
        if not callable(v):
            print(f'{a}: {v}')
    except:
        pass
print('---')
# Check opt attributes
for a in dir(m.opt):
    if not a.startswith('_'):
        try:
            v = getattr(m.opt, a)
            if not callable(v):
                print(f'opt.{a}: {v}')
        except:
            pass
" 2>&1

